<?php
require 'config.php'; require_admin();
$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $action=(string)($_POST['action']??''); $id=max(0,(int)($_POST['id']??0));
 if($action==='create'){
  $siteId=max(0,(int)($_POST['site_id']??0)); $interval=max(60,min(10080,(int)($_POST['interval_minutes']??1440)));
  $st=$pdo->prepare('SELECT id FROM sites WHERE id=?');$st->execute([$siteId]);
  if(!$st->fetch())$message='Hãy chọn cấu hình website hợp lệ.';
  else{$next=date('Y-m-d H:i:s',time()+$interval*60);$st=$pdo->prepare('INSERT INTO scan_schedules(site_id,interval_minutes,enabled,next_run_at) VALUES(?,?,1,?)');$st->execute([$siteId,$interval,$next]);$message='Đã tạo lịch giám sát. Hãy cấu hình Task Scheduler để worker chạy định kỳ.';}
 } elseif($action==='toggle'){$st=$pdo->prepare('SELECT enabled FROM scan_schedules WHERE id=?');$st->execute([$id]);$current=$st->fetchColumn();if($current!==false){$newEnabled=(int)$current===1?0:1;$next=$newEnabled?date('Y-m-d H:i:s'):null;$st=$pdo->prepare('UPDATE scan_schedules SET enabled=?, next_run_at=CASE WHEN ?=1 THEN ? ELSE next_run_at END WHERE id=?');$st->execute([$newEnabled,$newEnabled,$next,$id]);}$message='Đã cập nhật trạng thái lịch.';}
 elseif($action==='run_now'){$st=$pdo->prepare('UPDATE scan_schedules SET next_run_at=NOW(),enabled=1 WHERE id=?');$st->execute([$id]);$message='Lịch đã được đặt chạy ngay ở lượt worker tiếp theo.';}
 elseif($action==='delete'){$st=$pdo->prepare('DELETE FROM scan_schedules WHERE id=?');$st->execute([$id]);$message='Đã xóa lịch.';}
}
$sites=$pdo->query('SELECT id,name,start_url,created_at FROM sites ORDER BY id DESC')->fetchAll();
$schedules=$pdo->query('SELECT sc.*,s.name,s.start_url FROM scan_schedules sc JOIN sites s ON s.id=sc.site_id ORDER BY sc.id DESC')->fetchAll();
layout_start('Giám sát định kỳ'); ?>
<div class="d-flex justify-content-between align-items-start flex-wrap gap-3 mb-4"><div><div class="small-label mb-2">UPTIME & LINK MONITORING</div><h1 class="h3 page-title mb-1">Giám sát định kỳ</h1><p class="muted mb-0">Tạo lịch quét lặp lại và theo dõi lỗi mới qua trung tâm thông báo.</p></div><span class="badge text-bg-light">Windows Task Scheduler</span></div>
<?php if($message!==''):?><div class="alert alert-info"><?=e($message)?></div><?php endif;?>
<div class="row g-4"><div class="col-lg-5"><div class="card p-4"><h2 class="h5 fw-bold mb-1">Tạo lịch mới</h2><p class="small muted mb-4">Chọn một cấu hình website đã lưu từ phiên quét trước.</p><?php if(!$sites):?><div class="alert alert-warning">Chưa có cấu hình website. Hãy tạo phiên quét đầu tiên trước.</div><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="mb-3"><label class="form-label fw-semibold">Website / cấu hình</label><select class="form-select" name="site_id" required><?php foreach($sites as $site):?><option value="<?=$site['id']?>">#<?=$site['id']?> · <?=e($site['name'])?> — <?=e($site['start_url'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label fw-semibold">Chu kỳ quét</label><select class="form-select" name="interval_minutes"><option value="60">Mỗi 1 giờ</option><option value="360">Mỗi 6 giờ</option><option value="720">Mỗi 12 giờ</option><option value="1440" selected>Mỗi 24 giờ</option><option value="10080">Mỗi 7 ngày</option></select></div><button class="btn btn-primary w-100">＋ Tạo lịch giám sát</button></form><?php endif;?></div></div>
<div class="col-lg-7"><div class="card p-4"><h2 class="h5 fw-bold mb-1">Lịch đang cấu hình</h2><p class="small muted mb-3">Worker chạy lịch đến hạn, sau đó tạo phiên quét mới và thông báo khi phát hiện lỗi.</p><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Website</th><th>Chu kỳ</th><th>Trạng thái</th><th>Lần chạy tiếp</th><th>Thao tác</th></tr></thead><tbody><?php if(!$schedules):?><tr><td colspan="5" class="text-center py-4 muted">Chưa có lịch giám sát.</td></tr><?php endif;foreach($schedules as $sc):?><tr><td><strong><?=e($sc['name'])?></strong><div class="small muted wrap-url"><?=e($sc['start_url'])?></div></td><td><?=((int)$sc['interval_minutes']>=10080?'7 ngày':(((int)$sc['interval_minutes']%1440===0)?((int)$sc['interval_minutes']/1440).' ngày':(((int)$sc['interval_minutes']%60===0)?((int)$sc['interval_minutes']/60).' giờ':(int)$sc['interval_minutes'].' phút')))?></td><td><span class="badge text-bg-<?=$sc['enabled']?'success':'secondary'?>"><?=$sc['enabled']?'Đang bật':'Tạm dừng'?></span></td><td><?=e($sc['next_run_at']??'—')?></td><td><div class="d-flex flex-wrap gap-1"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$sc['id']?>"><input type="hidden" name="action" value="run_now"><button class="btn btn-sm btn-outline-primary">Chạy ngay</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$sc['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-sm btn-outline-secondary"><?=$sc['enabled']?'Tạm dừng':'Bật lại'?></button></form><form method="post" onsubmit="return confirm('Xóa lịch này?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$sc['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<div class="card p-4 mt-4"><h2 class="h5 fw-bold">Kích hoạt worker trên Windows</h2><ol class="mb-2"><li>Mở <strong>Task Scheduler</strong> → Create Basic Task.</li><li>Đặt lịch chạy lặp lại, ví dụ mỗi 5 phút.</li><li>Action: Start a program.</li><li>Program: <code>C:\xampp\php\php.exe</code></li><li>Arguments: <code>C:\xampp\htdocs\broken_link_checker_php\schedule_worker.php</code></li></ol><p class="small muted mb-0">Worker chỉ xử lý một lịch đến hạn mỗi lần chạy. Lịch “Chạy ngay” sẽ được thực hiện ở lượt worker tiếp theo.</p></div>
